param([ValidateSet('x86','x64')][string]$CompileArchitecture)
$ErrorActionPreference = 'Stop'
$repoRoot = Split-Path $PSScriptRoot -Parent
$source = Join-Path $repoRoot '.deps/dxvk-remix'
if (!$CompileArchitecture) {
  foreach ($architecture in @('x86','x64')) {
    & powershell.exe -NoProfile -File $PSCommandPath -CompileArchitecture $architecture
    if ($LASTEXITCODE -ne 0) { throw "Resource lifecycle tests failed: $architecture" }
  }
  exit 0
}
$testDir = Join-Path $repoRoot ".deps/resource-lifecycle-$CompileArchitecture"
New-Item -ItemType Directory -Force $testDir | Out-Null
. (Join-Path $source 'bridge/build_common.ps1')
SetupVS -Platform $CompileArchitecture -VcVarsVer '14.29'
Push-Location $testDir
try {
  python "$PSScriptRoot/prepare_resource_lifecycle_test.py" $source $testDir
  if ($LASTEXITCODE -ne 0) { throw 'Resource lifecycle extraction failed' }
  $compilerOptions = @('/nologo','/std:c++17','/EHsc','/W4','/WX',"/I$source/bridge/src/client","/I$testDir","$repoRoot/tests/resource_lifecycle.cpp")
  & cl.exe @compilerOptions /Fe:resource-lifecycle.exe
  if ($LASTEXITCODE -ne 0) { throw 'Resource lifecycle test compilation failed' }
  & ./resource-lifecycle.exe
  if ($LASTEXITCODE -ne 0) { throw 'Resource lifecycle test failed' }
  if ($CompileArchitecture -eq 'x86') {
    foreach ($control in @('VertexBuffer','IndexBuffer','RenderTarget','DepthStencilSurface','OffscreenPlainSurface','RenderTargetEx','OffscreenPlainSurfaceEx','DepthStencilSurfaceEx','offset','policy','host')) {
      python "$PSScriptRoot/prepare_resource_lifecycle_test.py" $source $testDir --negative-control $control
      if ($LASTEXITCODE -ne 0) { throw "Resource lifecycle negative extraction failed: $control" }
      & cl.exe @compilerOptions /Fe:resource-lifecycle-negative.exe
      if ($LASTEXITCODE -ne 0) { throw "Resource lifecycle negative compilation failed: $control" }
      & ./resource-lifecycle-negative.exe
      if ($LASTEXITCODE -eq 0) { throw "Resource lifecycle test missed the original failure: $control" }
    }
  }
} finally {
  python "$PSScriptRoot/prepare_resource_lifecycle_test.py" $source $testDir
  if ($LASTEXITCODE -ne 0) { throw 'Failed to restore actual resource lifecycle methods' }
  Pop-Location
}
